-- Let me understand: for each race, find the driver with pp=1 (fastest lap flag)
-- Also check what lap_times.lapval means - is it lap number?
SELECT rc_index, wheel_unit, lapval, pp FROM lap_times WHERE rc_index = 76 ORDER BY msec_val LIMIT 5;

-- Check what px values indicate points finish - typically top 10 get points in F1
-- Let's see driver_standings for a specific race to understand position vs points
SELECT drv_stnd, rlink, drive_link, acc_pt, px, px_desc FROM driver_standings WHERE rlink = 76 ORDER BY px LIMIT 20;

-- Check if px_desc having a value means points finish, or if px <= 10 means points finish
-- Let's look at driver_standings entries where acc_pt > 0 (got points)
SELECT DISTINCT acc_pt FROM driver_standings WHERE acc_pt IS NOT NULL AND acc_pt > 0 ORDER BY acc_pt LIMIT 20;

CREATE OR REPLACE FUNCTION award_hat_trick(p_driver_id INTEGER, p_race_id INTEGER)
RETURNS VOID AS $$
DECLARE
    v_has_pole BOOLEAN;
    v_has_winner BOOLEAN;
    v_has_fastest_lap BOOLEAN;
BEGIN
    -- Check Pole Position: driver set fastest lap in qualifying (px_pos = 1)
    SELECT EXISTS(
        SELECT 1 FROM qualifying 
        WHERE pilotrec = p_driver_id 
          AND rbind = p_race_id 
          AND px_pos = 1
    ) INTO v_has_pole;

    -- Check Race Winner: driver classified 1st in the race
    SELECT EXISTS(
        SELECT 1 FROM driver_standings 
        WHERE drive_link = p_driver_id 
          AND rlink = p_race_id 
          AND px = 1
    ) INTO v_has_winner;

    -- Check Fastest Lap Award: driver had fastest lap (min msec_val among pp=1) AND points finish (px <= 10)
    SELECT EXISTS(
        SELECT 1 FROM lap_times lt
        JOIN driver_standings ds ON lt.wheel_unit = ds.drive_link AND lt.rc_index = ds.rlink
        WHERE lt.rc_index = p_race_id 
          AND lt.wheel_unit = p_driver_id
          AND lt.pp = 1
          AND lt.msec_val = (SELECT MIN(lt2.msec_val) FROM lap_times lt2 WHERE lt2.rc_index = p_race_id AND lt2.pp = 1)
          AND ds.px IS NOT NULL 
          AND ds.px <= 10
    ) INTO v_has_fastest_lap;

    -- If all three conditions are met, insert into achievements table
    IF v_has_pole AND v_has_winner AND v_has_fastest_lap THEN
        INSERT INTO achievements (driver_id, race_id, achievement_type)
        VALUES (p_driver_id, p_race_id, 'Hat Trick');
    END IF;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE PROCEDURE award_hat_trick(p_driver_id INTEGER, p_race_id INTEGER)
LANGUAGE plpgsql AS $$
DECLARE
