    -- Check Race Winner
    SELECT EXISTS(
        SELECT 1 FROM driver_standings 
        WHERE drive_link = p_driver_id 
          AND rlink = p_race_id 
          AND px = 1
    ) INTO v_has_winner;

    -- Check Fastest Lap Award (fastest lap + points finish)
    SELECT EXISTS(
        SELECT 1 FROM lap_times lt
        JOIN driver_standings ds ON lt.wheel_unit = ds.drive_link AND lt.rc_index = ds.rlink
        WHERE lt.rc_index = p_race_id 
